def minimum_k_avoiding_sum(n,k):
    chosen=[];blocked=set();candidate=1
    while len(chosen)<n:
        if candidate not in blocked:
            chosen.append(candidate);blocked.add(k-candidate)
        candidate+=1
    return sum(chosen)

